local _abc = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local function _bxor(a,b)
    local r, bit = 0, 1
    while a > 0 or b > 0 do
        local aa, bb = a % 2, b % 2
