        local d = _abc:find(s:sub(i+3,i+3), 1, true)
        if a and b then
            a,b = a-1,b-1
            c = c and c-1 or 0
            d = d and d-1 or 0
            n=n+1; out[n]=string.char(a*4+math.floor(b/16))
